 10	import { describe, it, expect, beforeAll } from 'vitest';
 11	import { readFileSync } from 'node:fs';
 12	import { join } from 'node:path';
 13	import vm from 'node:vm';
 14	
 15	// ---------------------------------------------------------------------------
 16	// Load client scripts
 17	// ---------------------------------------------------------------------------
 18	
 19	const publicDir = join(__dirname, '../../gui/public');
 20	const projectDetailJs = readFileSync(join(publicDir, 'views/project-detail.js'), 'utf-8');
 21	
 22	beforeAll(() => {
 23	  // Install minimal stubs required by project-detail.js at parse time.
 24	  (globalThis as Record<string, unknown>)['marked'] = {
 25	    parse: (s: string) => '<p>' + s + '</p>',
 26	  };
 27	  (globalThis as Record<string, unknown>)['OrchestratorWidgets'] = {
 28	    renderStatusCard:    () => '',
 29	    renderKillButton:    () => document.createElement('button'),
 30	    renderDismissButton: () => {},
 31	    renderLogPreview:    () => () => {},
 32	    renderProgressBadge: () => '',
 33	    renderCliReference:  () => '',
