 43	// ---------------------------------------------------------------------------
 44	// Global type declaration
 45	// ---------------------------------------------------------------------------
 46	
 47	declare global {
 48	  // eslint-disable-next-line no-var
 49	  var _snapshotProjectState: (
 50	    project: Record<string, unknown>,
 51	    overviewResult: unknown[] | null
 52	  ) => {
 53	    status: string;
 54	    last_updated: string;
 55	    synthesis_generated: boolean;
 56	    wpStatuses: Record<string, { status: string; pipelineStages: unknown[] }>;
 57	    health: null | { work_packages_needing_reset: number };
 58	  };
 59	}
