 61	// ---------------------------------------------------------------------------
 62	// Helpers
 63	// ---------------------------------------------------------------------------
 64	
 65	/** Minimal valid project response from API.getProject */
 66	function makeProject(overrides: Record<string, unknown> = {}) {
 67	  return {
 68	    meta: {
 69	      status: 'IN_PROGRESS',
 70	      title: 'Test Project',
 71	      plan_path: '/some/path',
 72	      date_created: '2026-01-01T00:00:00Z',
 73	      last_updated: '2026-01-15T12:00:00Z',
 74	      ...overrides,
 75	    },
 76	    work_packages: [],
 77	    project_comments: [],
 78	    project_name: 'Test Project',
 79	    timing: null,
 80	    server_version: null,
 81	    ledger_version: null,
 82	    synthesis_generated: false,
 83	    ...overrides,
 84	  };
 85	}
 86	
 87	/** Minimal valid work package entry inside a project response */
 88	function makeWp(id: string, status = 'READY') {
 89	  return { work_package_id: id, status, assigned_to: 'Developer' };
 90	}
 91	
 92	/** Minimal valid overview entry from API.getWorkPackageOverview */
 93	function makeOverviewEntry(id: string, stages: unknown[] = []) {
 94	  return { work_package_id: id, pipeline_stages: stages };
 95	}
