 59	declare global {
 60	  // eslint-disable-next-line no-var
 61	  var _diffProjectState: (prev: Snapshot, next: Snapshot) => DiffResult;
 62	  // eslint-disable-next-line no-var
 63	  var _snapshotProjectState: (
 64	    project: Record<string, unknown>,
 65	    overviewResult: unknown[] | null
