 72	
 73	function makeSnapshot(overrides: Partial<Snapshot> = {}): Snapshot {
 74	  return {
 75	    status: 'IN_PROGRESS',
 76	    last_updated: '2026-01-15T12:00:00Z',
 77	    synthesis_generated: false,
 78	    wpStatuses: {
 79	      'WP-001': { status: 'IN_PROGRESS', pipelineStages: [] },
 80	      'WP-002': { status: 'READY',       pipelineStages: [] },
 81	    },
 82	    health: null,
 83	    ...overrides,
 84	  };
